begin; select plan(9);
insert into auth.users(id,email) values('00000000-0000-0000-0000-00000000000a','a@t');
set local role authenticated; set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-00000000000a"}';
create temp table ctx as select create_family_with_defaults('A') fid;
insert into wallets(family_id,name,kind,initial_balance) select fid,'W1','bank',1000 from ctx;
insert into wallets(family_id,name,kind) select fid,'W2','cash' from ctx;
create temp table w as select (select id from wallets where name='W1') a,(select id from wallets where name='W2') b,(select id from categories where type='expense' limit 1) cat;
select create_transfer((select fid from ctx),a,b,300,current_date,10,cat,null,'k1') from w;
select is((select balance from wallet_balances where name='W1')::int,690,'saldo W1 = 1000-300-10');
select is((select balance from wallet_balances where name='W2')::int,300,'saldo W2 = 300');
select throws_ok($$select create_transfer((select fid from ctx),a,a,5,current_date) from w$$,'23514',null,'transfer ke dompet sama ditolak');
select throws_ok($$select create_transfer((select fid from ctx),a,b,5,current_date,0,null,null,'k1') from w$$,'23505',null,'idempotency key mencegah duplikat');
select is(((dashboard_summary((select fid from ctx),current_date,current_date))->>'expense')::int,10,'transfer tidak dihitung pengeluaran, biaya dihitung');
insert into debts(family_id,direction,counterparty,principal) select fid,'payable','X',100 from ctx;
select throws_ok($$select pay_debt((select id from debts),150,current_date,(select a from w),(select cat from w))$$,'23514',null,'pembayaran melebihi sisa ditolak');
select pay_debt((select id from debts),100,current_date,(select a from w),(select cat from w));
select is((select status from debts),'paid','utang lunas setelah dibayar penuh');
insert into recurring_transactions(family_id,type,wallet_id,category_id,amount,frequency,start_date) select (select fid from ctx),'expense',a,cat,50,'monthly','2026-01-01' from w;
reset role;
select is(run_recurring('2026-03-15'),3,'recurring membuat 3 kejadian');
select is(run_recurring('2026-03-15'),0,'recurring idempotent: eksekusi ulang tidak menggandakan');
select * from finish(); rollback;